"""MLIR textual format parser."""
from __future__ import annotations
from typing import List, Optional, Dict, Tuple
from enum import Enum, auto
from .ir import (
    Operation, Region, Block, Type, IntegerType, FloatType, IndexType,
    MemRefType, TensorType, FunctionType, NoneType, Attribute, IntegerAttr,
    FloatAttr, StringAttr, ArrayAttr, Value, OpResult, MLIRContext
)


class TokenKind(Enum):
    """Token types for the MLIR lexer."""
    PERCENT = auto()
    AT = auto()
    HASH = auto()
    EQUAL = auto()
    ARROW = auto()
    COLON = auto()
    COMMA = auto()
    LPAREN = auto()
    RPAREN = auto()
    LBRACE = auto()
    RBRACE = auto()
    LBRACKET = auto()
    RBRACKET = auto()
    LANGLE = auto()
    RANGLE = auto()
    INTEGER_LITERAL = auto()
    FLOAT_LITERAL = auto()
    STRING_LITERAL = auto()
    BARE_IDENTIFIER = auto()
    CARET_IDENTIFIER = auto()
    KEYWORD = auto()
    EOF = auto()
    STAR = auto()
    QUESTION = auto()
    ELLIPSIS = auto()


class Token:
    """A single lexer token."""

    def __init__(self, kind: TokenKind, value: str, line: int, col: int) -> None:
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self) -> str:
        return f"Token({self.kind}, {self.value!r})"


class Lexer:
    """Tokenizer for MLIR textual format."""

    KEYWORDS = frozenset([
        "func", "module", "return", "br", "cond_br", "memref", "tensor",
        "index", "none", "true", "false", "dense", "loc", "attributes"
    ])

    def __init__(self, source: str) -> None:
        self._source = source
        self._pos = 0
        self._line = 1
        self._col = 1
        self._tokens: List[Token] = []
        self._tokenize()

    def _peek_char(self) -> str:
        if self._pos >= len(self._source):
            return ""
        return self._source[self._pos]

    def _advance(self) -> str:
        ch = self._source[self._pos]
        self._pos += 1
        if ch == "\n":
            self._line += 1
            self._col = 1
        else:
            self._col += 1
        return ch

    def _skip_whitespace_and_comments(self) -> None:
        while self._pos < len(self._source):
            ch = self._source[self._pos]
            if ch in " \t\r\n":
                self._advance()
            elif ch == "/" and self._pos + 1 < len(self._source) and self._source[self._pos + 1] == "/":
                while self._pos < len(self._source) and self._source[self._pos] != "\n":
                    self._advance()
            else:
                break

    def _read_string(self) -> str:
        self._advance()  # consume opening quote
        result = []
        while self._pos < len(self._source):
            ch = self._advance()
            if ch == '"':
                return "".join(result)
            elif ch == '\\':
                next_ch = self._advance()
                if next_ch == 'n':
                    result.append('\n')
                elif next_ch == 't':
                    result.append('\t')
                elif next_ch == '\\':
                    result.append('\\')
                elif next_ch == '"':
                    result.append('"')
                else:
                    result.append(next_ch)
            else:
                result.append(ch)
        raise ParseError("Unterminated string literal", self._line, self._col)

    def _read_number(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        is_float = False
        if self._source[self._pos] == '-':
            self._advance()
        while self._pos < len(self._source) and self._source[self._pos].isdigit():
            self._advance()
        if self._pos < len(self._source) and self._source[self._pos] == '.':
            is_float = True
            self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        if self._pos < len(self._source) and self._source[self._pos] in ('e', 'E'):
            is_float = True
            self._advance()
            if self._pos < len(self._source) and self._source[self._pos] in ('+', '-'):
                self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.FLOAT_LITERAL if is_float else TokenKind.INTEGER_LITERAL
        return Token(kind, value, line, col)

    def _read_identifier(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        while self._pos < len(self._source) and (self._source[self._pos].isalnum() or self._source[self._pos] in '_$.'):
            self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.KEYWORD if value in self.KEYWORDS else TokenKind.BARE_IDENTIFIER
        return Token(kind, value, line, col)

    def _tokenize(self) -> None:
        simple_tokens = {
            '%': TokenKind.PERCENT, '@': TokenKind.AT, '#': TokenKind.HASH,
            '=': TokenKind.EQUAL, ':': TokenKind.COLON, ',': TokenKind.COMMA,
            '(': TokenKind.LPAREN, ')': TokenKind.RPAREN,
            '{': TokenKind.LBRACE, '}': TokenKind.RBRACE,
            '[': TokenKind.LBRACKET, ']': TokenKind.RBRACKET,
            '<': TokenKind.LANGLE, '>': TokenKind.RANGLE,
            '*': TokenKind.STAR, '?': TokenKind.QUESTION,
        }
        while self._pos < len(self._source):
            self._skip_whitespace_and_comments()
            if self._pos >= len(self._source):
                break
            ch = self._source[self._pos]
            line, col = self._line, self._col
            if ch == '-' and self._pos + 1 < len(self._source) and self._source[self._pos + 1] == '>':
                self._advance()
                self._advance()
                self._tokens.append(Token(TokenKind.ARROW, "->", line, col))
            elif ch == '^':
                self._advance()
                start = self._pos
                while self._pos < len(self._source) and (self._source[self._pos].isalnum() or self._source[self._pos] == '_'):
                    self._advance()
                self._tokens.append(Token(TokenKind.CARET_IDENTIFIER, self._source[start:self._pos], line, col))
            elif ch == '"':
                value = self._read_string()
                self._tokens.append(Token(TokenKind.STRING_LITERAL, value, line, col))
            elif ch.isdigit() or (ch == '-' and self._pos + 1 < len(self._source) and self._source[self._pos + 1].isdigit()):
                self._tokens.append(self._read_number())
            elif ch.isalpha() or ch == '_':
                self._tokens.append(self._read_identifier())
            elif ch in simple_tokens:
                self._advance()
                self._tokens.append(Token(simple_tokens[ch], ch, line, col))
            else:
                self._advance()
        self._tokens.append(Token(TokenKind.EOF, "", self._line, self._col))

    @property
    def tokens(self) -> List[Token]:
        return self._tokens


class ParseError(Exception):
    """Error raised during parsing."""

    def __init__(self, message: str, line: int = 0, col: int = 0) -> None:
        self.line = line
        self.col = col
        super().__init__(f"Parse error at {line}:{col}: {message}")


class Parser:
    """Recursive descent parser for MLIR textual format."""

    def __init__(self, source: str, context: Optional[MLIRContext] = None) -> None:
        self._lexer = Lexer(source)
        self._tokens = self._lexer.tokens
        self._pos = 0
        self._context = context or MLIRContext()
        self._ssa_values: Dict[str, Value] = {}
        self._block_map: Dict[str, Block] = {}

    def _current(self) -> Token:
        return self._tokens[self._pos]

    def _peek(self) -> Token:
        if self._pos + 1 < len(self._tokens):
            return self._tokens[self._pos + 1]
        return self._tokens[-1]

    def _advance(self) -> Token:
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _expect(self, kind: TokenKind) -> Token:
        tok = self._current()
        if tok.kind != kind:
            raise ParseError(f"Expected {kind}, got {tok.kind}", tok.line, tok.col)
