    def _print_op(self, op: Operation) -> None:
        indent = self._indent()
        name_str = str(op.name)
        if name_str == "builtin.module":
            self._print_module(op)
            return
        if name_str == "builtin.func" or name_str == "func.func":
            self._print_function(op)
            return
        result_str = ""
        if op.results:
            names = [self._name_state.get_value_name(r) for r in op.results]
            result_str = ", ".join(names) + " = "
