    """Dead Code Elimination."""

    def run_on_function(self, func: Operation) -> bool:
        changed = False
        for region in func.regions:
            for block in region.blocks:
                changed |= self._dce_block(block)
        return changed

    def _dce_block(self, block: Block) -> bool:
        changed = False
        to_remove: List[Operation] = []
        for op in reversed(block.operations):
            if op == block.terminator:
                continue
            if self._is_dead(op):
                to_remove.append(op)
                changed = True
                self.increment_statistic("num_dead_eliminated")
        for op in to_remove:
            op.erase()
        return changed

    def _is_dead(self, op: Operation) -> bool:
        if op.regions:
            return False
        return all(result.use_empty() for result in op.results)


