        changed = False
        func_table: Dict[str, Operation] = {}
        self._build_func_table(module, func_table)
        call_ops: List[Operation] = []
        module.walk(lambda op: call_ops.append(op) if str(op.name) == "func.call" else None)
        for call_op in call_ops:
            callee_attr = call_op.get_attr("callee")
            if callee_attr is None:
                continue
            callee_name = str(callee_attr).strip('"').lstrip('@')
            if callee_name in func_table:
                callee = func_table[callee_name]
                if self._should_inline(callee):
                    self._inline_call(call_op, callee)
                    changed = True
                    self.increment_statistic("num_inlined")
        return changed

    def _build_func_table(self, module: Operation, table: Dict[str, Operation]) -> None:
        for region in module.regions:
            for block in region.blocks:
                for op in block.operations:
                    if str(op.name) in ("builtin.func", "func.func"):
                        name_attr = op.get_attr("sym_name")
                        if name_attr:
                            table[str(name_attr).strip('"')] = op

    def _should_inline(self, func: Operation) -> bool:
        if not func.regions or func.regions[0].empty():
            return False
        op_count = 0
        for block in func.regions[0].blocks:
            op_count += len(block.operations)
        return op_count <= self._max_inline_size

    def _inline_call(self, call_op: Operation, callee: Operation) -> None:
        pass


