    """Constant folding pass."""

    def run_on_function(self, func: Operation) -> bool:
        changed = False
        ops_to_process: List[Operation] = []
        func.walk(lambda op: ops_to_process.append(op))
        for op in ops_to_process:
            if self._try_fold(op):
                changed = True
                self.increment_statistic("num_folded")
        return changed

    def _try_fold(self, op: Operation) -> bool:
        name = str(op.name)
        if name == "arith.addi":
            return self._fold_binary_int(op, lambda a, b: a + b)
        elif name == "arith.muli":
            return self._fold_binary_int(op, lambda a, b: a * b)
        elif name == "arith.subi":
            return self._fold_binary_int(op, lambda a, b: a - b)
        return False

    def _fold_binary_int(self, op: Operation, fn: Callable[[int, int], int]) -> bool:
        if len(op._operands) != 2:
            return False
        lhs_op = self._get_constant_op(op._operands[0].value)
        rhs_op = self._get_constant_op(op._operands[1].value)
        if lhs_op is None or rhs_op is None:
            return False
        lhs_attr = lhs_op.get_attr("value")
        rhs_attr = rhs_op.get_attr("value")
        if not isinstance(lhs_attr, IntegerAttr) or not isinstance(rhs_attr, IntegerAttr):
            return False
        result_val = fn(lhs_attr.value, rhs_attr.value)
        op.set_attr("value", IntegerAttr(result_val, lhs_attr.type))
        op._name = OperationName("arith.constant")
        return True

    def _get_constant_op(self, value: Value) -> Optional[Operation]:
        if isinstance(value, OpResult):
            owner = value.owner
            if str(owner.name) == "arith.constant":
                return owner
        return None
