"""MLIR pass infrastructure."""
from __future__ import annotations
from typing import List, Optional, Dict, Set, Callable, Type as PyType
from abc import ABC, abstractmethod
from .ir import Operation, Region, Block, Value, OpResult, Attribute, IntegerAttr, OperationName


class AnalysisResult:
    """Base class for analysis results."""

    def __init__(self) -> None:
        self._preserved = True

    @property
    def preserved(self) -> bool:
        return self._preserved

    def invalidate(self) -> None:
        self._preserved = False


class DominanceInfo(AnalysisResult):
    """Dominance analysis for a region."""

    def __init__(self, region: Region) -> None:
        super().__init__()
        self._dominators: Dict[int, Set[int]] = {}
        self._compute(region)

    def _compute(self, region: Region) -> None:
        for block in region.blocks:
            block_id = id(block)
            self._dominators[block_id] = {block_id}

    def dominates(self, a: Block, b: Block) -> bool:
        b_id = id(b)
        if b_id not in self._dominators:
            return False
        return id(a) in self._dominators[b_id]


class AnalysisManager:
    """Manages analysis results for operations."""

    def __init__(self) -> None:
        self._analyses: Dict[str, AnalysisResult] = {}

    def get_analysis(self, name: str) -> Optional[AnalysisResult]:
        return self._analyses.get(name)

    def cache_analysis(self, name: str, result: AnalysisResult) -> None:
        self._analyses[name] = result

    def invalidate(self, name: str) -> None:
        if name in self._analyses:
            self._analyses[name].invalidate()
            del self._analyses[name]

    def invalidate_all(self) -> None:
        self._analyses.clear()


class Pass(ABC):
    """Base class for all passes."""

    def __init__(self) -> None:
        self._name = self.__class__.__name__
        self._statistics: Dict[str, int] = {}

    @property
    def name(self) -> str:
        return self._name

    @abstractmethod
    def run_on_operation(self, op: Operation) -> bool:
        """Run the pass on an operation. Returns True if IR was modified."""
        pass

    def get_statistic(self, name: str) -> int:
        return self._statistics.get(name, 0)

    def increment_statistic(self, name: str) -> None:
        self._statistics[name] = self._statistics.get(name, 0) + 1


class FunctionPass(Pass):
    """Pass that operates on function-level operations."""

    def run_on_operation(self, op: Operation) -> bool:
        if str(op.name) in ("builtin.func", "func.func"):
            return self.run_on_function(op)
        changed = False
        for region in op.regions:
            for block in region.blocks:
                for inner_op in block.operations:
                    if str(inner_op.name) in ("builtin.func", "func.func"):
                        changed |= self.run_on_function(inner_op)
        return changed

    @abstractmethod
    def run_on_function(self, func: Operation) -> bool:
        pass


class ModulePass(Pass):
    """Pass that operates on the entire module."""

    def run_on_operation(self, op: Operation) -> bool:
        return self.run_on_module(op)

    @abstractmethod
    def run_on_module(self, module: Operation) -> bool:
        pass


class PassManager:
    """Manages and executes a pipeline of passes."""

    def __init__(self) -> None:
        self._passes: List[Pass] = []
        self._analysis_manager = AnalysisManager()
        self._pass_statistics: Dict[str, Dict[str, int]] = {}

    def add_pass(self, pass_instance: Pass) -> "PassManager":
        self._passes.append(pass_instance)
        return self

    def run(self, op: Operation) -> bool:
        """Run all passes in the pipeline. Returns True if any pass modified the IR."""
        overall_changed = False
        for p in self._passes:
            changed = p.run_on_operation(op)
            if changed:
                overall_changed = True
                self._analysis_manager.invalidate_all()
            self._pass_statistics[p.name] = dict(p._statistics)
        return overall_changed

    def nest_pass_manager(self) -> "PassManager":
        nested = PassManager()
        nested._analysis_manager = self._analysis_manager
        return nested

    @property
    def statistics(self) -> Dict[str, Dict[str, int]]:
        return self._pass_statistics


class Canonicalizer(FunctionPass):
    """Canonicalization pass applying local rewrite patterns."""

    def __init__(self, max_iterations: int = 10) -> None:
        super().__init__()
        self._max_iterations = max_iterations

    def run_on_function(self, func: Operation) -> bool:
        changed = False
        for iteration in range(self._max_iterations):
            local_changed = False
            ops_to_process: List[Operation] = []
            func.walk(lambda op: ops_to_process.append(op))
            for op in ops_to_process:
                if self._try_canonicalize(op):
                    local_changed = True
                    self.increment_statistic("num_canonicalized")
            if not local_changed:
                break
            changed = True
        return changed

    def _try_canonicalize(self, op: Operation) -> bool:
        if str(op.name) == "arith.constant":
            return False
        if self._fold_constant_operands(op):
            return True
        return False

    def _fold_constant_operands(self, op: Operation) -> bool:
        if len(op._operands) < 2:
            return False
        all_constant = all(
            self._is_constant_op(self._get_defining_op(operand.value))
            for operand in op._operands
        )
        if all_constant and str(op.name) == "arith.addi":
            return self._fold_addi(op)
        return False

    def _is_constant_op(self, op: Optional[Operation]) -> bool:
        return op is not None and str(op.name) == "arith.constant"

    def _get_defining_op(self, value: Value) -> Optional[Operation]:
        if isinstance(value, OpResult):
