class PatternBenefit:
    """Represents the benefit of applying a pattern."""

    def __init__(self, benefit: int = 1) -> None:
        if benefit < 0:
            raise ValueError("Pattern benefit must be non-negative")
        self._benefit = benefit

    @property
    def value(self) -> int:
        return self._benefit

    def __lt__(self, other: PatternBenefit) -> bool:
        return self._benefit < other._benefit

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PatternBenefit):
            return False
        return self._benefit == other._benefit

    @staticmethod
    def impossible() -> PatternBenefit:
        return PatternBenefit(0)


class RewritePattern(ABC):
    """Base class for rewrite patterns."""

    def __init__(self, root_op_name: str, benefit: int = 1) -> None:
        self._root_op_name = root_op_name
        self._benefit = PatternBenefit(benefit)

    @property
    def root_operation_name(self) -> str:
        return self._root_op_name

    @property
    def benefit(self) -> PatternBenefit:
        return self._benefit

    @abstractmethod
    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        """Attempt to match and rewrite the operation. Return True on success."""
        pass

    def match(self, op: Operation) -> bool:
        """Check if the pattern matches without performing the rewrite."""
        return str(op.name) == self._root_op_name


class PatternRewriter:
    """Provides methods for pattern rewrite implementations."""

    def __init__(self) -> None:
        self._erased_ops: List[Operation] = []
        self._created_ops: List[Operation] = []
        self._replacements: Dict[int, Value] = {}

    def replace_op(self, op: Operation, new_values: List[Value]) -> None:
        """Replace all results of an operation with new values."""
        for i, result in enumerate(op.results):
            if i < len(new_values):
                result.replace_all_uses_with(new_values[i])
                self._replacements[id(result)] = new_values[i]
        self.erase_op(op)

    def replace_op_with_new_op(self, op: Operation, new_op: Operation) -> None:
        """Replace an operation with a new operation."""
        if op.parent_block:
            block = op.parent_block
            idx = block.operations.index(op)
            block.insert_operation(idx, new_op)
        self.replace_op(op, list(new_op.results))

    def erase_op(self, op: Operation) -> None:
        """Erase an operation from its parent block."""
        self._erased_ops.append(op)
        op.erase()

    def create_operation(self, name: str, operands: List[Value] = None,
                         result_types: List[Type] = None,
                         attributes: Dict[str, Attribute] = None) -> Operation:
        """Create a new operation."""
        new_op = Operation(name, operands=operands, result_types=result_types,
                          attributes=attributes)
        self._created_ops.append(new_op)
        return new_op

    def insert_before(self, op: Operation, new_op: Operation) -> None:
        """Insert a new operation before the given operation."""
        if op.parent_block:
            op.parent_block.insert_before(new_op, op)

    def insert_after(self, op: Operation, new_op: Operation) -> None:
        """Insert a new operation after the given operation."""
        if op.parent_block:
            op.parent_block.insert_after(new_op, op)

    def set_insertion_point_before(self, op: Operation) -> None:
        """Set the insertion point to just before an operation."""
        self._insertion_point = op

