"""Comb (Combinational) dialect - combinational logic operations for CIRCT."""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import List, Optional


class CombOp:
    """Base class for combinational operations."""
    op_name: str = "comb.unknown"
    width: int = 0
    operands: List[str] = []
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        raise NotImplementedError

    def fold(self, constants: dict) -> Optional[int]:
        """Attempt constant folding. Returns None if not foldable."""
        return None

    def infer_width(self, type_env: dict) -> int:
        """Infer result width from operand types."""
        return self.width


@dataclass
class AddOp(CombOp):
    """Combinational addition: result = a + b (mod 2^width)."""
    op_name: str = "comb.add"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        mask = (1 << self.width) - 1
        a = env[self.operands[0]] & mask
        b = env[self.operands[1]] & mask
        return (a + b) & mask

    def fold(self, constants: dict) -> Optional[int]:
        if all(op in constants for op in self.operands):
            mask = (1 << self.width) - 1
            return (constants[self.operands[0]] + constants[self.operands[1]]) & mask
        return None


@dataclass
class SubOp(CombOp):
    """Combinational subtraction: result = a - b (mod 2^width)."""
    op_name: str = "comb.sub"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        mask = (1 << self.width) - 1
        a = env[self.operands[0]] & mask
        b = env[self.operands[1]] & mask
        return (a - b) & mask

    def fold(self, constants: dict) -> Optional[int]:
        if all(op in constants for op in self.operands):
            mask = (1 << self.width) - 1
            return (constants[self.operands[0]] - constants[self.operands[1]]) & mask
        return None


