@dataclass
class ICmpOp(CombOp):
    """Integer comparison operation with configurable predicate."""
    op_name: str = "comb.icmp"
    predicate: str = "eq"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        mask = (1 << self.width) - 1
        a = env[self.operands[0]] & mask
        b = env[self.operands[1]] & mask
        if self.predicate == "eq":
            return 1 if a == b else 0
        elif self.predicate == "ne":
            return 1 if a != b else 0
        elif self.predicate == "sgt":
            return 1 if a > b else 0
        elif self.predicate == "slt":
            return 1 if a < b else 0
        elif self.predicate == "uge":
            return 1 if a >= b else 0
        elif self.predicate == "ule":
            return 1 if a <= b else 0
        return 0

    def infer_width(self, type_env: dict) -> int:
        return 1


@dataclass
class MuxOp(CombOp):
    """Two-input multiplexer: result = cond ? true_val : false_val."""
    op_name: str = "comb.mux"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        cond = env[self.operands[0]]
        true_val = env[self.operands[1]]
        false_val = env[self.operands[2]]
        mask = (1 << self.width) - 1
        return (true_val if cond else false_val) & mask


@dataclass
class ConcatOp(CombOp):
    """Bit concatenation of multiple operands."""
    op_name: str = "comb.concat"
    operands: List[str] = field(default_factory=list)
    operand_widths: List[int] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        result = 0
        shift = 0
        for i in range(len(self.operands) - 1, -1, -1):
            val = env[self.operands[i]] & ((1 << self.operand_widths[i]) - 1)
            result |= val << shift
            shift += self.operand_widths[i]
        return result & ((1 << self.width) - 1)

    def infer_width(self, type_env: dict) -> int:
        return sum(self.operand_widths)


