        mask = (1 << self.width) - 1
        if self.reset and env.get(self.reset, 0):
            self.current_value = self.reset_value & mask
        else:
            self.current_value = env.get(self.input_signal, 0) & mask
        return self.current_value

    def async_reset(self, env: Dict[str, int]) -> bool:
        if self.reset_type == ResetType.ASYNC and self.reset:
            if env.get(self.reset, 0):
                self.current_value = self.reset_value & ((1 << self.width) - 1)
                return True
        return False

    def get_value(self) -> int:
