"""High-Level Synthesis pipeline scheduling for K-CIRCT."""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import List, Dict, Optional, Set, Tuple


@dataclass
class ScheduleNode:
    """A node in the scheduling graph representing an operation."""
    name: str
    op_type: str
    latency: int = 1
    scheduled_cycle: int = -1
    resource_type: str = "alu"
    predecessors: List[str] = field(default_factory=list)
    successors: List[str] = field(default_factory=list)

    def is_scheduled(self) -> bool:
        return self.scheduled_cycle >= 0

    def earliest_start(self, schedule: Dict[str, int], latencies: Dict[str, int]) -> int:
        if not self.predecessors:
            return 0
        return max(
            schedule.get(p, 0) + latencies.get(p, 1)
            for p in self.predecessors
            if p in schedule
        ) if any(p in schedule for p in self.predecessors) else 0


@dataclass
class PipelineStage:
    """Represents a single stage in a pipelined design."""
    stage_id: int
    operations: List[str] = field(default_factory=list)
    registers_in: List[str] = field(default_factory=list)
    registers_out: List[str] = field(default_factory=list)
    resource_usage: Dict[str, int] = field(default_factory=dict)

    def add_operation(self, op_name: str, resource: str = "alu") -> None:
        self.operations.append(op_name)
        self.resource_usage[resource] = self.resource_usage.get(resource, 0) + 1

    def utilization(self, resource: str, limit: int) -> float:
        used = self.resource_usage.get(resource, 0)
        return used / limit if limit > 0 else 0.0

    def operation_count(self) -> int:
        return len(self.operations)

    def add_pipeline_register(self, signal: str) -> None:
        self.registers_out.append(signal)


class HLSScheduler:
    """High-Level Synthesis scheduler with multiple algorithms."""

    def __init__(self) -> None:
        self.nodes: Dict[str, ScheduleNode] = {}
        self.schedule: Dict[str, int] = {}
        self.resource_limits: Dict[str, int] = {"alu": 4, "mul": 2, "mem": 2}
        self.latency_table: Dict[str, int] = {
            "add": 1, "sub": 1, "mul": 3, "div": 10,
            "load": 2, "store": 1, "cmp": 1, "phi": 0,
        }

    def add_node(self, name: str, op_type: str, predecessors: List[str] = None) -> None:
        latency = self.latency_table.get(op_type, 1)
        resource = "mul" if op_type in ("mul", "div") else "mem" if op_type in ("load", "store") else "alu"
        node = ScheduleNode(
            name=name, op_type=op_type, latency=latency,
            resource_type=resource, predecessors=predecessors or [],
        )
        self.nodes[name] = node
        for pred in node.predecessors:
            if pred in self.nodes:
                self.nodes[pred].successors.append(name)

    def schedule_asap(self) -> Dict[str, int]:
        self.schedule = {}
        topo_order = self._topological_sort()
        for name in topo_order:
            node = self.nodes[name]
            start = 0
            for pred in node.predecessors:
                if pred in self.schedule:
                    pred_end = self.schedule[pred] + self.nodes[pred].latency
                    start = max(start, pred_end)
            self.schedule[name] = start
            node.scheduled_cycle = start
        return dict(self.schedule)

    def schedule_alap(self, deadline: int) -> Dict[str, int]:
        self.schedule = {}
        reverse_topo = list(reversed(self._topological_sort()))
        for name in reverse_topo:
            node = self.nodes[name]
            if not node.successors:
                end_time = deadline - node.latency
            else:
                end_time = min(
                    self.schedule.get(s, deadline) for s in node.successors
                ) - node.latency
            self.schedule[name] = max(0, end_time)
            node.scheduled_cycle = self.schedule[name]
        return dict(self.schedule)

    def schedule_list(self) -> Dict[str, int]:
        self.schedule = {}
        ready: List[str] = []
        scheduled_set: Set[str] = set()
        for name, node in self.nodes.items():
            if not node.predecessors:
                ready.append(name)
        cycle = 0
        max_iterations = len(self.nodes) * 20
        iteration = 0
        while len(scheduled_set) < len(self.nodes) and iteration < max_iterations:
            iteration += 1
            resource_usage: Dict[str, int] = {}
            ready.sort(key=lambda n: len(self.nodes[n].successors), reverse=True)
            scheduled_this_cycle: List[str] = []
            for name in list(ready):
                node = self.nodes[name]
                res = node.resource_type
                used = resource_usage.get(res, 0)
                limit = self.resource_limits.get(res, 4)
                if used < limit:
                    self.schedule[name] = cycle
                    node.scheduled_cycle = cycle
                    resource_usage[res] = used + 1
                    scheduled_this_cycle.append(name)
                    scheduled_set.add(name)
            for name in scheduled_this_cycle:
                ready.remove(name)
            cycle += 1
            for name, node in self.nodes.items():
                if name not in scheduled_set and name not in ready:
                    if all(p in scheduled_set and self.schedule[p] + self.nodes[p].latency <= cycle
                           for p in node.predecessors):
                        ready.append(name)
        return dict(self.schedule)

    def compute_initiation_interval(self) -> int:
        if not self.schedule:
            return 1
        resource_per_cycle: Dict[int, Dict[str, int]] = {}
        for name, cycle in self.schedule.items():
            node = self.nodes[name]
            for c in range(cycle, cycle + node.latency):
                if c not in resource_per_cycle:
                    resource_per_cycle[c] = {}
                res = node.resource_type
                resource_per_cycle[c][res] = resource_per_cycle[c].get(res, 0) + 1
        min_ii = 1
        for cycle_usage in resource_per_cycle.values():
            for res, count in cycle_usage.items():
                limit = self.resource_limits.get(res, 4)
                needed_ii = (count + limit - 1) // limit
                min_ii = max(min_ii, needed_ii)
        return min_ii

    def total_schedule_length(self) -> int:
        if not self.schedule:
            return 0
        max_end = 0
        for name, cycle in self.schedule.items():
            end = cycle + self.nodes[name].latency
            max_end = max(max_end, end)
        return max_end

    def build_pipeline_stages(self) -> List[PipelineStage]:
        if not self.schedule:
            return []
        num_stages = self.total_schedule_length()
        stages = [PipelineStage(stage_id=i) for i in range(num_stages)]
        for name, cycle in self.schedule.items():
            node = self.nodes[name]
            if 0 <= cycle < num_stages:
                stages[cycle].add_operation(name, node.resource_type)
        return stages

    def _topological_sort(self) -> List[str]:
        visited: Set[str] = set()
        order: List[str] = []

        def dfs(name: str) -> None:
            if name in visited:
                return
            visited.add(name)
            for pred in self.nodes[name].predecessors:
                if pred in self.nodes:
                    dfs(pred)
            order.append(name)

        for name in self.nodes:
            dfs(name)
        return order


class ModuloScheduler:
    """Modulo scheduling for loop pipelining."""

    def __init__(self, initiation_interval: int = 1) -> None:
        self.ii: int = initiation_interval
        self.nodes: Dict[str, ScheduleNode] = {}
        self.schedule: Dict[str, Tuple[int, int]] = {}

    def add_node(self, name: str, op_type: str, latency: int = 1,
                 predecessors: List[str] = None) -> None:
        node = ScheduleNode(
            name=name, op_type=op_type, latency=latency,
            predecessors=predecessors or [],
        )
        self.nodes[name] = node

    def schedule_modulo(self) -> Dict[str, Tuple[int, int]]:
        self.schedule = {}
        topo_order = self._topological_sort()
        for name in topo_order:
            node = self.nodes[name]
            earliest = 0
            for pred in node.predecessors:
                if pred in self.schedule:
                    pred_cycle, _ = self.schedule[pred]
                    pred_lat = self.nodes[pred].latency
                    earliest = max(earliest, pred_cycle + pred_lat)
            slot = earliest % self.ii
            stage = earliest // self.ii
            self.schedule[name] = (earliest, stage)
            node.scheduled_cycle = earliest
        return dict(self.schedule)

    def kernel_length(self) -> int:
        if not self.schedule:
            return 0
        max_stage = max(stage for _, stage in self.schedule.values())
        return (max_stage + 1) * self.ii

    def prologue_length(self) -> int:
        if not self.schedule:
            return 0
        max_stage = max(stage for _, stage in self.schedule.values())
        return max_stage * self.ii

    def epilogue_length(self) -> int:
        return self.prologue_length()

    def _topological_sort(self) -> List[str]:
        visited: Set[str] = set()
        order: List[str] = []

        def dfs(name: str) -> None:
            if name in visited:
                return
            visited.add(name)
            for pred in self.nodes[name].predecessors:
                if pred in self.nodes:
                    dfs(pred)
            order.append(name)

        for name in self.nodes:
            dfs(name)
        return order
