    @property
    def dialect(self) -> str:
        return self._dialect

    @property
    def mnemonic(self) -> str:
        return self._mnemonic

    def __str__(self) -> str:
        return f"!{self._dialect}.{self._mnemonic}"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, OpaqueType):
            return False
        return self._dialect == other._dialect and self._mnemonic == other._mnemonic

    def __hash__(self) -> int:
        return hash(("opaque", self._dialect, self._mnemonic))


class MemRefType(Type):
    """Multi-dimensional memory reference type."""

    def __init__(self, shape: List[int], element_type: Type,
                 memory_space: int = 0) -> None:
        self._shape = list(shape)
        self._element_type = element_type
        self._memory_space = memory_space

    @property
    def shape(self) -> List[int]:
        return self._shape

    @property
    def element_type(self) -> Type:
        return self._element_type

    @property
    def rank(self) -> int:
        return len(self._shape)

    def has_static_shape(self) -> bool:
        return all(d >= 0 for d in self._shape)

    def get_num_elements(self) -> int:
        if not self.has_static_shape():
            raise ValueError("Cannot compute num elements for dynamic shape")
        result = 1
        for d in self._shape:
            result *= d
        return result

    def __str__(self) -> str:
        dims = "x".join("?" if d < 0 else str(d) for d in self._shape)
        return f"memref<{dims}x{self._element_type}>"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, MemRefType):
            return False
        return (self._shape == other._shape and
                self._element_type == other._element_type and
                self._memory_space == other._memory_space)

    def __hash__(self) -> int:
        return hash(("memref", tuple(self._shape), self._element_type))


class TensorType(Type):
    """Multi-dimensional tensor type."""

    def __init__(self, shape: List[int], element_type: Type) -> None:
        self._shape = list(shape)
        self._element_type = element_type

    @property
    def shape(self) -> List[int]:
        return self._shape

    @property
    def element_type(self) -> Type:
        return self._element_type

    @property
    def rank(self) -> int:
        return len(self._shape)

    def has_static_shape(self) -> bool:
        return all(d >= 0 for d in self._shape)

    def __str__(self) -> str:
        dims = "x".join("?" if d < 0 else str(d) for d in self._shape)
        return f"tensor<{dims}x{self._element_type}>"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, TensorType):
            return False
        return self._shape == other._shape and self._element_type == other._element_type

    def __hash__(self) -> int:
        return hash(("tensor", tuple(self._shape), self._element_type))


class FunctionType(Type):
    """Function type with inputs and results."""

    def __init__(self, inputs: List[Type], results: List[Type]) -> None:
        self._inputs = list(inputs)
        self._results = list(results)

    @property
    def inputs(self) -> List[Type]:
        return self._inputs

    @property
    def results(self) -> List[Type]:
        return self._results

    def __str__(self) -> str:
        inputs_str = ", ".join(str(t) for t in self._inputs)
        if len(self._results) == 1:
            return f"({inputs_str}) -> {self._results[0]}"
        results_str = ", ".join(str(t) for t in self._results)
        return f"({inputs_str}) -> ({results_str})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FunctionType):
            return False
        return self._inputs == other._inputs and self._results == other._results

    def __hash__(self) -> int:
        return hash(("func", tuple(self._inputs), tuple(self._results)))


class Attribute(ABC):
    """Base class for all MLIR attributes."""

    @abstractmethod
    def __str__(self) -> str:
        pass


class IntegerAttr(Attribute):
    def __init__(self, value: int, type: IntegerType) -> None:
        self._value = value
        self._type = type

    @property
    def value(self) -> int:
        return self._value

    @property
    def type(self) -> IntegerType:
        return self._type

    def __str__(self) -> str:
        return f"{self._value} : {self._type}"


class FloatAttr(Attribute):
    def __init__(self, value: float, type: FloatType) -> None:
        self._value = value
        self._type = type

    @property
    def value(self) -> float:
        return self._value

    @property
    def type(self) -> FloatType:
        return self._type

    def __str__(self) -> str:
        return f"{self._value:g} : {self._type}"


class StringAttr(Attribute):
    def __init__(self, value: str) -> None:
        self._value = value

    @property
    def value(self) -> str:
        return self._value

    def __str__(self) -> str:
        escaped = self._value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'


class ArrayAttr(Attribute):
    def __init__(self, elements: List[Attribute]) -> None:
        self._elements = list(elements)

    @property
    def elements(self) -> List[Attribute]:
        return self._elements

    def __len__(self) -> int:
        return len(self._elements)

    def __getitem__(self, index: int) -> Attribute:
        return self._elements[index]

    def __str__(self) -> str:
        return "[" + ", ".join(str(e) for e in self._elements) + "]"


class DenseElementsAttr(Attribute):
    def __init__(self, type: TensorType, values: List[Any]) -> None:
        self._type = type
        self._values = list(values)

    @property
    def type(self) -> TensorType:
        return self._type

    @property
    def values(self) -> List[Any]:
        return self._values

    def __str__(self) -> str:
        vals = ", ".join(str(v) for v in self._values)
        return f"dense<[{vals}]> : {self._type}"


class Value:
    """Represents an SSA value."""

    def __init__(self, type: Type) -> None:
        self._type = type
        self._uses: List[OpOperand] = []

    @property
    def type(self) -> Type:
        return self._type

    @property
    def uses(self) -> List[OpOperand]:
        return self._uses

    def add_use(self, operand: OpOperand) -> None:
        self._uses.append(operand)

    def remove_use(self, operand: OpOperand) -> None:
        if operand in self._uses:
            self._uses.remove(operand)

    def replace_all_uses_with(self, new_value: Value) -> None:
        for use in list(self._uses):
            use.set_value(new_value)

    def has_one_use(self) -> bool:
        return len(self._uses) == 1

    def use_empty(self) -> bool:
        return len(self._uses) == 0


class BlockArgument(Value):
    """An SSA value produced by entering a block."""

    def __init__(self, type: Type, block: Block, index: int) -> None:
        super().__init__(type)
        self._block = block
        self._index = index

    @property
    def owner(self) -> Block:
        return self._block

    @property
    def arg_number(self) -> int:
        return self._index


class OpResult(Value):
    """An SSA value produced by an operation."""

    def __init__(self, type: Type, owner: Operation, index: int) -> None:
        super().__init__(type)
        self._owner = owner
        self._index = index

    @property
    def owner(self) -> Operation:
        return self._owner

    @property
    def result_number(self) -> int:
        return self._index


class OpOperand:
    """A single use of a value by an operation."""

    def __init__(self, owner: Operation, value: Value, index: int) -> None:
        self._owner = owner
        self._value = value
        self._index = index
        value.add_use(self)

    @property
    def owner(self) -> Operation:
        return self._owner

    @property
    def value(self) -> Value:
        return self._value

    @property
    def index(self) -> int:
        return self._index

    def set_value(self, new_value: Value) -> None:
        self._value.remove_use(self)
        self._value = new_value
        new_value.add_use(self)


class OperationName:
    """The fully qualified name of an operation, e.g. `arith.addi`."""

    def __init__(self, name: str) -> None:
        self._name = name

    @property
    def dialect_name(self) -> str:
        parts = self._name.split(".", 1)
        return parts[0] if len(parts) > 1 else ""

    @property
    def stripped_name(self) -> str:
        parts = self._name.split(".", 1)
        return parts[1] if len(parts) > 1 else self._name

    def __str__(self) -> str:
        return self._name

    def __repr__(self) -> str:
        return f"OperationName({self._name!r})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, str):
            return self._name == other
        if isinstance(other, OperationName):
            return self._name == other._name
        return False

    def __hash__(self) -> int:
        return hash(self._name)


class Operation:
    """Core operation class in MLIR."""

    def __init__(self, name: str, operands: List[Value] = None,
                 result_types: List[Type] = None,
                 attributes: Dict[str, Attribute] = None,
                 regions: List[Region] = None) -> None:
        self._name = OperationName(name)
        self._operands: List[OpOperand] = []
        self._results: List[OpResult] = []
        self._attributes: Dict[str, Attribute] = attributes or {}
        self._regions: List[Region] = regions or []
        self._parent_block: Optional[Block] = None
        self._successors: List[Block] = []
        for i, val in enumerate(operands or []):
            self._operands.append(OpOperand(self, val, i))
        for i, typ in enumerate(result_types or []):
            self._results.append(OpResult(typ, self, i))
        for region in self._regions:
            region._parent_op = self

    @property
    def name(self) -> OperationName:
        return self._name

    @property
    def operands(self) -> List[Value]:
        return [operand.value for operand in self._operands]

    @property
    def num_operands(self) -> int:
        return len(self._operands)

    @property
    def results(self) -> List[OpResult]:
        return self._results

    @property
    def attributes(self) -> Dict[str, Attribute]:
        return self._attributes

    @property
    def regions(self) -> List[Region]:
        return self._regions

    @property
    def successors(self) -> List[Block]:
        return self._successors

    @property
    def parent_block(self) -> Optional[Block]:
        return self._parent_block

    @property
    def parent_op(self) -> Optional[Operation]:
        if self._parent_block is None:
            return None
        region = self._parent_block.parent_region
        return region.parent_op if region is not None else None

    def get_operand(self, index: int) -> Value:
        return self._operands[index].value

    def set_operand(self, index: int, value: Value) -> None:
        self._operands[index].set_value(value)

    def get_result(self, index: int) -> OpResult:
        return self._results[index]

    def set_attr(self, name: str, attr: Attribute) -> None:
        self._attributes[name] = attr

    def get_attr(self, name: str) -> Optional[Attribute]:
        return self._attributes.get(name)

    def has_trait_terminator(self) -> bool:
        return bool(self._successors) or str(self._name) in (
            "return", "func.return", "cf.br", "cf.cond_br", "hw.output",
        )

    def add_region(self) -> Region:
        region = Region()
        region._parent_op = self
        self._regions.append(region)
        return region

    def erase(self) -> None:
        if self._parent_block:
            self._parent_block.remove_operation(self)
        for operand in self._operands:
            operand.value.remove_use(operand)

    def walk(self, callback: Callable) -> None:
        """Pre-order walk over this operation and everything nested inside it."""
        callback(self)
        for region in self._regions:
            for block in region.blocks:
                for op in list(block.operations):
                    op.walk(callback)

    def __repr__(self) -> str:
        return f"Operation({str(self._name)!r})"


class Region:
    """Contains a list of blocks."""

    def __init__(self) -> None:
        self._blocks: List[Block] = []
        self._parent_op: Optional[Operation] = None

    @property
    def blocks(self) -> List[Block]:
        return self._blocks

    @property
    def parent_op(self) -> Optional[Operation]:
        return self._parent_op

    def add_block(self) -> Block:
        block = Block()
        block._parent_region = self
        self._blocks.append(block)
        return block

    def push_block(self, block: Block) -> Block:
        block._parent_region = self
        self._blocks.append(block)
        return block

    @property
    def entry_block(self) -> Optional[Block]:
        return self._blocks[0] if self._blocks else None

    def empty(self) -> bool:
        return len(self._blocks) == 0


class Block:
    """A basic block containing operations."""

    def __init__(self, arg_types: List[Type] = None) -> None:
        self._arguments: List[BlockArgument] = []
        self._operations: List[Operation] = []
        self._parent_region: Optional[Region] = None
        for i, t in enumerate(arg_types or []):
            self._arguments.append(BlockArgument(t, self, i))

    @property
    def arguments(self) -> List[BlockArgument]:
        return self._arguments

    @property
    def operations(self) -> List[Operation]:
        return self._operations

    @property
    def parent_region(self) -> Optional[Region]:
        return self._parent_region

    @property
    def parent_op(self) -> Optional[Operation]:
        return self._parent_region.parent_op if self._parent_region else None

    def add_argument(self, type: Type) -> BlockArgument:
        arg = BlockArgument(type, self, len(self._arguments))
        self._arguments.append(arg)
        return arg

    def add_operation(self, op: Operation) -> None:
        op._parent_block = self
        self._operations.append(op)

    def insert_operation(self, index: int, op: Operation) -> None:
        op._parent_block = self
        self._operations.insert(index, op)

    def remove_operation(self, op: Operation) -> None:
        self._operations.remove(op)
        op._parent_block = None

    def insert_before(self, new_op: Operation, before: Operation) -> None:
        idx = self._operations.index(before)
        self.insert_operation(idx, new_op)

    def insert_after(self, new_op: Operation, after: Operation) -> None:
        idx = self._operations.index(after) + 1
        self.insert_operation(idx, new_op)

    @property
    def terminator(self) -> Optional[Operation]:
        return self._operations[-1] if self._operations else None

    def successors(self) -> List[Block]:
        term = self.terminator
        return list(term.successors) if term is not None else []

    def empty(self) -> bool:
        return len(self._operations) == 0

