"""MLIR textual format parser."""
from __future__ import annotations
from typing import List, Optional, Dict, Tuple
from enum import Enum, auto
from .ir import (
    Operation, Region, Block, Type, IntegerType, FloatType, IndexType,
    MemRefType, TensorType, FunctionType, NoneType, OpaqueType, Attribute,
    IntegerAttr, FloatAttr, StringAttr, ArrayAttr, Value, OpResult, MLIRContext
)


class TokenKind(Enum):
    """Token types for the MLIR lexer."""
    PERCENT = auto()
    AT = auto()
    HASH = auto()
    EQUAL = auto()
    ARROW = auto()
    COLON = auto()
    COMMA = auto()
    LPAREN = auto()
    RPAREN = auto()
    LBRACE = auto()
    RBRACE = auto()
    LBRACKET = auto()
    RBRACKET = auto()
    LANGLE = auto()
    RANGLE = auto()
    INTEGER_LITERAL = auto()
    FLOAT_LITERAL = auto()
    STRING_LITERAL = auto()
    BARE_IDENTIFIER = auto()
    CARET_IDENTIFIER = auto()
    EXCLAIM = auto()
    KEYWORD = auto()
    EOF = auto()
    STAR = auto()
    QUESTION = auto()
    ELLIPSIS = auto()


class Token:
    """A single lexer token."""

    def __init__(self, kind: TokenKind, value: str, line: int, col: int) -> None:
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self) -> str:
        return f"Token({self.kind}, {self.value!r})"


class ParseError(Exception):
    """Error raised during parsing."""

    def __init__(self, message: str, line: int = 0, col: int = 0) -> None:
        self.line = line
        self.col = col
        super().__init__(f"Parse error at {line}:{col}: {message}")


class Lexer:
    """Tokenizer for MLIR textual format."""

    KEYWORDS = frozenset([
        "func", "module", "return", "br", "cond_br", "memref", "tensor",
        "index", "none", "true", "false", "dense", "loc", "attributes"
    ])

    SIMPLE_TOKENS = {
        '%': TokenKind.PERCENT, '@': TokenKind.AT, '#': TokenKind.HASH,
        '=': TokenKind.EQUAL, ':': TokenKind.COLON, ',': TokenKind.COMMA,
        '(': TokenKind.LPAREN, ')': TokenKind.RPAREN,
        '{': TokenKind.LBRACE, '}': TokenKind.RBRACE,
        '[': TokenKind.LBRACKET, ']': TokenKind.RBRACKET,
        '<': TokenKind.LANGLE, '>': TokenKind.RANGLE,
        '*': TokenKind.STAR, '?': TokenKind.QUESTION,
        '!': TokenKind.EXCLAIM,
    }

    def __init__(self, source: str) -> None:
        self._source = source
        self._pos = 0
        self._line = 1
        self._col = 1
        self._tokens: List[Token] = []
        self._tokenize()

    def _peek_char(self) -> str:
        if self._pos >= len(self._source):
            return ""
        return self._source[self._pos]

    def _advance(self) -> str:
        ch = self._source[self._pos]
        self._pos += 1
        if ch == "\n":
            self._line += 1
            self._col = 1
        else:
            self._col += 1
        return ch

    def _skip_whitespace_and_comments(self) -> None:
        while self._pos < len(self._source):
            ch = self._source[self._pos]
            if ch in " \t\r\n":
                self._advance()
            elif (ch == "/" and self._pos + 1 < len(self._source)
                  and self._source[self._pos + 1] == "/"):
                while self._pos < len(self._source) and self._source[self._pos] != "\n":
                    self._advance()
            else:
                break

    def _read_string(self) -> str:
        self._advance()  # consume opening quote
        result = []
        while self._pos < len(self._source):
            ch = self._advance()
            if ch == '"':
                return "".join(result)
            elif ch == '\\':
                next_ch = self._advance()
                if next_ch == 'n':
                    result.append('\n')
                elif next_ch == 't':
                    result.append('\t')
                elif next_ch == '\\':
                    result.append('\\')
                elif next_ch == '"':
                    result.append('"')
                else:
                    result.append(next_ch)
            else:
                result.append(ch)
        raise ParseError("Unterminated string literal", self._line, self._col)

    def _read_number(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        is_float = False
        if self._source[self._pos] == '-':
            self._advance()
        while self._pos < len(self._source) and self._source[self._pos].isdigit():
            self._advance()
        if self._pos < len(self._source) and self._source[self._pos] == '.':
            is_float = True
            self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        if self._pos < len(self._source) and self._source[self._pos] in ('e', 'E'):
            is_float = True
            self._advance()
            if self._pos < len(self._source) and self._source[self._pos] in ('+', '-'):
                self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.FLOAT_LITERAL if is_float else TokenKind.INTEGER_LITERAL
        return Token(kind, value, line, col)

    def _read_identifier(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        while (self._pos < len(self._source) and
               (self._source[self._pos].isalnum() or self._source[self._pos] in '_$.')):
            self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.KEYWORD if value in self.KEYWORDS else TokenKind.BARE_IDENTIFIER
        return Token(kind, value, line, col)

    def _tokenize(self) -> None:
        while self._pos < len(self._source):
            self._skip_whitespace_and_comments()
            if self._pos >= len(self._source):
                break
            ch = self._source[self._pos]
            line, col = self._line, self._col
            next_ch = self._source[self._pos + 1] if self._pos + 1 < len(self._source) else ""
            if ch == '-' and next_ch == '>':
                self._advance()
                self._advance()
                self._tokens.append(Token(TokenKind.ARROW, "->", line, col))
            elif ch == '^':
                self._advance()
                start = self._pos
                while (self._pos < len(self._source) and
                       (self._source[self._pos].isalnum() or self._source[self._pos] == '_')):
                    self._advance()
                self._tokens.append(
                    Token(TokenKind.CARET_IDENTIFIER, self._source[start:self._pos], line, col))
            elif ch == '"':
                value = self._read_string()
                self._tokens.append(Token(TokenKind.STRING_LITERAL, value, line, col))
            elif ch.isdigit() or (ch == '-' and next_ch.isdigit()):
                self._tokens.append(self._read_number())
            elif ch.isalpha() or ch == '_':
                self._tokens.append(self._read_identifier())
            elif ch in self.SIMPLE_TOKENS:
                self._advance()
                self._tokens.append(Token(self.SIMPLE_TOKENS[ch], ch, line, col))
            else:
                self._advance()
        self._tokens.append(Token(TokenKind.EOF, "", self._line, self._col))

    @property
    def tokens(self) -> List[Token]:
        return self._tokens


class Parser:
    """Recursive descent parser for MLIR textual format."""

    def __init__(self, source: str, context: Optional[MLIRContext] = None) -> None:
        self._lexer = Lexer(source)
        self._tokens = self._lexer.tokens
        self._pos = 0
        self._context = context or MLIRContext()
        self._ssa_values: Dict[str, Value] = {}
        self._block_map: Dict[str, Block] = {}

    @property
    def context(self) -> MLIRContext:
        return self._context

    @property
    def ssa_values(self) -> Dict[str, Value]:
        return self._ssa_values

    def _current(self) -> Token:
        return self._tokens[self._pos]

    def _peek(self) -> Token:
        if self._pos + 1 < len(self._tokens):
            return self._tokens[self._pos + 1]
        return self._tokens[-1]

    def _advance(self) -> Token:
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _expect(self, kind: TokenKind) -> Token:
        tok = self._current()
        if tok.kind != kind:
            raise ParseError(f"Expected {kind}, got {tok.kind}", tok.line, tok.col)
        return self._advance()

    def _match(self, kind: TokenKind) -> Optional[Token]:
        if self._current().kind == kind:
            return self._advance()
        return None

    def parse_module(self) -> Operation:
        """Parse a top-level module."""
        if self._current().value == "module":
            self._advance()
        region = self._parse_region()
        module_op = Operation("builtin.module", regions=[region])
        return module_op

    def _parse_region(self) -> Region:
        self._expect(TokenKind.LBRACE)
        region = Region()
        while self._current().kind != TokenKind.RBRACE:
            block = self._parse_block()
            region._blocks.append(block)
            block._parent_region = region
        self._expect(TokenKind.RBRACE)
        return region

    def _parse_block(self) -> Block:
        block = Block()
        if self._current().kind == TokenKind.CARET_IDENTIFIER:
            label = self._advance().value
            self._block_map[label] = block
            if self._match(TokenKind.LPAREN):
                while self._current().kind != TokenKind.RPAREN:
                    self._expect(TokenKind.PERCENT)
                    name = self._advance().value
                    self._expect(TokenKind.COLON)
                    arg_type = self._parse_type()
                    arg = block.add_argument(arg_type)
                    self._ssa_values[name] = arg
                    self._match(TokenKind.COMMA)
                self._expect(TokenKind.RPAREN)
            self._expect(TokenKind.COLON)
        while (self._current().kind != TokenKind.RBRACE and
               self._current().kind != TokenKind.CARET_IDENTIFIER and
               self._current().kind != TokenKind.EOF):
            op = self._parse_operation()
            block.add_operation(op)
        return block

    def _parse_operation(self) -> Operation:
        result_names: List[str] = []
        if self._current().kind == TokenKind.PERCENT:
            result_names = self._parse_result_list()
            self._expect(TokenKind.EQUAL)
        op_name = self._parse_operation_name()
        attrs: Dict[str, Attribute] = {}
        if self._current().kind == TokenKind.AT:
            self._advance()
            sym_name = self._advance().value
            attrs["sym_name"] = StringAttr(sym_name)
        block_args: List[Tuple[str, Type]] = []
        if op_name in ("func.func", "builtin.func"):
            block_args = self._parse_func_args()
            operands: List[Value] = []
        else:
            operands = self._parse_operand_list()
        while self._current().kind in (TokenKind.INTEGER_LITERAL, TokenKind.FLOAT_LITERAL):
            tok = self._advance()
            if tok.kind == TokenKind.INTEGER_LITERAL:
                attrs.setdefault("value", IntegerAttr(int(tok.value), IntegerType(64)))
            self._match(TokenKind.COMMA)
        successors = self._parse_optional_successors()
        if self._current().kind == TokenKind.ARROW:
            self._advance()
            result_types = [self._parse_type()]
        else:
            result_types = []
        regions: List[Region] = []
        if (self._current().kind == TokenKind.LBRACE and
                op_name not in ("return", "cf.br", "cf.cond_br")):
            for arg_name, arg_type in block_args:
                self._ssa_values[arg_name] = Value(arg_type)
            regions.append(self._parse_region())
        if self._current().kind == TokenKind.COLON:
            self._advance()
            result_types = self._parse_function_type_or_type_list()
        op = Operation(op_name, operands=operands, result_types=result_types,
                       attributes=attrs, regions=regions)
        op._successors = successors
        for i, name in enumerate(result_names):
            if i < len(op.results):
                self._ssa_values[name] = op.get_result(i)
        return op

    def _parse_func_args(self) -> List[Tuple[str, Type]]:
        args: List[Tuple[str, Type]] = []
        if not self._match(TokenKind.LPAREN):
            return args
        while self._current().kind != TokenKind.RPAREN:
            self._expect(TokenKind.PERCENT)
            name = self._advance().value
            self._expect(TokenKind.COLON)
            arg_type = self._parse_type()
            args.append((name, arg_type))
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        return args

    def _parse_result_list(self) -> List[str]:
        names: List[str] = []
        while self._current().kind == TokenKind.PERCENT:
            self._advance()
            names.append(self._advance().value)
            if not self._match(TokenKind.COMMA):
                break
        return names

    def _parse_operation_name(self) -> str:
        return self._advance().value

    def _parse_operand_list(self) -> List[Value]:
        operands: List[Value] = []
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN:
                self._expect(TokenKind.PERCENT)
                name = self._advance().value
                if name in self._ssa_values:
                    operands.append(self._ssa_values[name])
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        else:
            # Leading bare keywords such as the `sgt` predicate of arith.cmpi.
            while self._current().kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
                self._advance()
                self._match(TokenKind.COMMA)
            while self._current().kind == TokenKind.PERCENT:
                self._advance()
                name = self._advance().value
                if name in self._ssa_values:
                    operands.append(self._ssa_values[name])
                if not self._match(TokenKind.COMMA):
                    break
        return operands

    def _parse_optional_successors(self) -> List[Block]:
        successors: List[Block] = []
        while self._current().kind == TokenKind.CARET_IDENTIFIER:
            if self._peek().kind == TokenKind.COLON:
                break
            label = self._advance().value
            if label in self._block_map:
                successors.append(self._block_map[label])
            self._match(TokenKind.COMMA)
        return successors

    def _parse_optional_attributes(self) -> Dict[str, Attribute]:
        attrs: Dict[str, Attribute] = {}
        if not self._match(TokenKind.LBRACE):
            return attrs
        while self._current().kind != TokenKind.RBRACE:
            key = self._advance().value
            self._expect(TokenKind.EQUAL)
            value = self._parse_attribute_value()
            attrs[key] = value
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RBRACE)
        return attrs

    def _parse_attribute_value(self) -> Attribute:
        tok = self._current()
        if tok.kind == TokenKind.INTEGER_LITERAL:
            self._advance()
            int_val = int(tok.value)
            if self._match(TokenKind.COLON):
                attr_type = self._parse_type()
                if isinstance(attr_type, IntegerType):
                    return IntegerAttr(int_val, attr_type)
            return IntegerAttr(int_val, IntegerType(64))
        elif tok.kind == TokenKind.FLOAT_LITERAL:
            self._advance()
            float_val = float(tok.value)
            if self._match(TokenKind.COLON):
                attr_type = self._parse_type()
                if isinstance(attr_type, FloatType):
                    return FloatAttr(float_val, attr_type)
            return FloatAttr(float_val, FloatType(64))
        elif tok.kind == TokenKind.STRING_LITERAL:
            self._advance()
            return StringAttr(tok.value)
        else:
            self._advance()
            return StringAttr(tok.value)

    def _parse_type(self) -> Type:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            return self._parse_opaque_type()
        if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
            name = tok.value
            if name.startswith("i") and name[1:].isdigit():
                self._advance()
                return IntegerType(int(name[1:]))
            elif name.startswith("f") and name[1:].isdigit():
                self._advance()
                return FloatType(int(name[1:]))
            elif name == "index":
                self._advance()
                return IndexType()
            elif name == "none":
                self._advance()
                return NoneType()
            elif name == "memref":
                return self._parse_memref_type()
            elif name == "tensor":
                return self._parse_tensor_type()
            else:
                self._advance()
                return IndexType()
        elif tok.kind == TokenKind.LPAREN:
            return self._parse_function_type()
        self._advance()
        return IndexType()

    def _parse_opaque_type(self) -> Type:
        self._expect(TokenKind.EXCLAIM)
        name = self._advance().value
        if "." in name:
            dialect, mnemonic = name.split(".", 1)
        else:
            dialect, mnemonic = name, ""
        return OpaqueType(dialect, mnemonic)

    def _parse_memref_type(self) -> MemRefType:
        self._advance()  # consume 'memref'
        self._expect(TokenKind.LANGLE)
        shape = self._parse_dimension_list()
        element_type = self._parse_type()
        self._expect(TokenKind.RANGLE)
        return MemRefType(shape, element_type)

    def _parse_tensor_type(self) -> TensorType:
        self._advance()  # consume 'tensor'
        self._expect(TokenKind.LANGLE)
        shape = self._parse_dimension_list()
        element_type = self._parse_type()
        self._expect(TokenKind.RANGLE)
        return TensorType(shape, element_type)

    def _parse_dimension_list(self) -> List[int]:
        dims: List[int] = []
        while True:
            if self._current().kind == TokenKind.QUESTION:
                self._advance()
                dims.append(-1)
            elif self._current().kind == TokenKind.INTEGER_LITERAL:
                dims.append(int(self._advance().value))
            else:
                break
            if self._current().value == "x":
                self._advance()
            else:
                break
        return dims

    def _parse_function_type(self) -> FunctionType:
        self._expect(TokenKind.LPAREN)
        inputs: List[Type] = []
        while self._current().kind != TokenKind.RPAREN:
            inputs.append(self._parse_type())
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        self._expect(TokenKind.ARROW)
        results: List[Type] = []
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN:
                results.append(self._parse_type())
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        else:
            results.append(self._parse_type())
        return FunctionType(inputs, results)

    def _parse_function_type_or_type_list(self) -> List[Type]:
        if self._current().kind == TokenKind.LPAREN:
            ft = self._parse_function_type()
            return ft.results
        types = [self._parse_type()]
        while self._match(TokenKind.COMMA):
            types.append(self._parse_type())
        return types


def parse(source: str, context: Optional[MLIRContext] = None) -> Operation:
    """Parse MLIR source text and return the top-level operation."""
    parser = Parser(source, context)
    return parser.parse_module()


def parse_file(path: str, context: Optional[MLIRContext] = None) -> Operation:
    """Parse an MLIR source file and return the top-level operation."""
    with open(path) as handle:
        return parse(handle.read(), context)

