"""MLIR textual format printer."""
from __future__ import annotations
from typing import Dict, List, Optional
from io import StringIO
from .ir import (
    Operation, Region, Block, Value, OpResult, BlockArgument,
    Type, IntegerType, FloatType, IndexType, NoneType, MemRefType,
    TensorType, FunctionType, Attribute, IntegerAttr, FloatAttr,
    StringAttr, ArrayAttr, DenseElementsAttr
)


class SSANameState:
    """Manages SSA value naming during printing."""

    def __init__(self) -> None:
        self._value_names: Dict[int, str] = {}
        self._next_value_id: int = 0
        self._next_block_id: int = 0
        self._block_names: Dict[int, str] = {}

    def get_value_name(self, value: Value) -> str:
        vid = id(value)
        if vid not in self._value_names:
            self._value_names[vid] = f"%{self._next_value_id}"
            self._next_value_id += 1
        return self._value_names[vid]

    def get_block_name(self, block: Block) -> str:
        bid = id(block)
        if bid not in self._block_names:
            self._block_names[bid] = f"^bb{self._next_block_id}"
            self._next_block_id += 1
        return self._block_names[bid]

    def set_value_name(self, value: Value, name: str) -> None:
        self._value_names[id(value)] = name


class Printer:
    """Prints MLIR operations in textual format."""

    def __init__(self, indent_size: int = 2) -> None:
        self._output = StringIO()
        self._indent_level = 0
        self._indent_size = indent_size
        self._name_state = SSANameState()

    def print_operation(self, op: Operation) -> str:
        """Print an operation and return the resulting string."""
        self._print_op(op)
        return self._output.getvalue()

    def _indent(self) -> str:
        return " " * (self._indent_level * self._indent_size)

    def _print_op(self, op: Operation) -> None:
        indent = self._indent()
        name_str = str(op.name)
        if name_str == "builtin.module":
            self._print_module(op)
            return
        if name_str in ("builtin.func", "func.func"):
            self._print_function(op)
            return
        result_str = ""
        if op.results:
            names = [self._name_state.get_value_name(r) for r in op.results]
            result_str = ", ".join(names) + " = "
        operand_strs = [self._name_state.get_value_name(operand.value)
                        for operand in op._operands]
        operands_str = "(" + ", ".join(operand_strs) + ")" if operand_strs else "()"
        attrs_str = self._format_attributes(op.attributes)
        type_str = self._format_op_result_types(op)
        self._output.write(f"{indent}{result_str}\"{name_str}\"{operands_str}")
        if attrs_str:
            self._output.write(f" {attrs_str}")
        if op.regions:
            self._output.write(" ")
            for region in op.regions:
                self._print_region(region)
        self._output.write(f" : {type_str}\n")

    def _print_module(self, op: Operation) -> None:
        self._output.write("module")
        attrs_str = self._format_attributes(op.attributes)
        if attrs_str:
            self._output.write(f" attributes {attrs_str}")
        self._output.write(" {\n")
        self._indent_level += 1
        if op.regions:
            for block in op.regions[0].blocks:
                for inner_op in block.operations:
                    self._print_op(inner_op)
        self._indent_level -= 1
        self._output.write("}\n")

    def _print_function(self, op: Operation) -> None:
        indent = self._indent()
        func_name = ""
        if "sym_name" in op.attributes:
            func_name = str(op.attributes["sym_name"]).strip('"')
        self._output.write(f"{indent}func.func @{func_name}")
        func_type = op.attributes.get("function_type")
        if func_type:
            self._output.write(f" {func_type}")
        if op.regions and not op.regions[0].empty():
            self._output.write(" {\n")
            self._indent_level += 1
            for block in op.regions[0].blocks:
                self._print_block(block)
            self._indent_level -= 1
            self._output.write(f"{indent}}}\n")
        else:
            self._output.write("\n")

    def _print_region(self, region: Region) -> None:
        self._output.write("{\n")
        self._indent_level += 1
        for block in region.blocks:
            self._print_block(block)
        self._indent_level -= 1
        self._output.write(self._indent() + "}")

    def _print_block(self, block: Block) -> None:
        indent = self._indent()
        needs_label = bool(block.arguments) or (
            block.parent_region is not None and
            block.parent_region.blocks.index(block) > 0
        )
        if needs_label:
            block_name = self._name_state.get_block_name(block)
            arg_strs = []
            for arg in block.arguments:
                name = self._name_state.get_value_name(arg)
                arg_strs.append(f"{name}: {arg.type}")
            args = "(" + ", ".join(arg_strs) + ")" if arg_strs else ""
            self._output.write(f"{indent}{block_name}{args}:\n")
        for op in block.operations:
            self._print_op(op)

    def _format_attributes(self, attrs: Dict[str, Attribute]) -> str:
        if not attrs:
            return ""
        pairs = []
        for key, value in attrs.items():
            if key in ("sym_name", "function_type"):
                continue
            pairs.append(f"{key} = {value}")
        if not pairs:
            return ""
        return "{" + ", ".join(pairs) + "}"

    def _format_op_result_types(self, op: Operation) -> str:
        if not op.results:
            return "()"
        types = [str(r.type) for r in op.results]
        if len(types) == 1:
            return types[0]
        return "(" + ", ".join(types) + ")"

    def _format_type(self, type: Type) -> str:
        return str(type)


def print_operation(op: Operation) -> str:
    """Convenience function to print an operation."""
    printer = Printer()
    return printer.print_operation(op)


def print_module(module: Operation) -> str:
    """Print a module operation."""
    return print_operation(module)


class PrettyPrinter(Printer):
    """Extended printer with additional formatting options."""

    def __init__(self, indent_size: int = 2, use_local_scope: bool = False) -> None:
        super().__init__(indent_size)
        self._use_local_scope = use_local_scope

    def print_with_local_scope(self, op: Operation) -> str:
        """Print operation with locally scoped SSA names."""
        self._name_state = SSANameState()
        self._print_op(op)
        return self._output.getvalue()

    def format_location(self, op: Operation) -> str:
        """Format location information for an operation."""
        loc = op.get_attr("loc")
        if loc:
            return f" loc({loc})"
        return ""

