                changed |= self._dce_block(block)
        return changed

    def _dce_block(self, block: Block) -> bool:
        changed = False
        to_remove: List[Operation] = []
        for op in reversed(block.operations):
            if op is block.terminator:
                continue
            if self._is_dead(op):
