"""MLIR pass infrastructure."""
from __future__ import annotations
from typing import List, Optional, Dict, Set, Callable, Type as PyType
from abc import ABC, abstractmethod
from .ir import (
    Operation, Region, Block, Value, OpResult, Attribute, IntegerAttr,
    OperationName
