        rhs_attr = rhs_op.get_attr("value")
        if isinstance(lhs_attr, IntegerAttr) and isinstance(rhs_attr, IntegerAttr):
            new_val = lhs_attr.value + rhs_attr.value
            op.set_attr("value", IntegerAttr(new_val, lhs_attr.type))
            return True
        return False


