    def add_pattern(self, pattern: RewritePattern) -> None:
        self._patterns.append(pattern)

    def apply(self, op: Operation) -> bool:
        """Apply dialect conversion to the operation tree."""
        changed = False
        illegal_ops: List[Operation] = []
        op.walk(lambda o: illegal_ops.append(o) if not self._target.is_legal(o) else None)
        sorted_patterns = sorted(self._patterns, key=lambda p: p.benefit.value, reverse=True)
        for illegal_op in illegal_ops:
