    """Convenience base for operation-specific rewrite patterns."""

    def __init__(self, op_name: str, benefit: int = 1) -> None:
        super().__init__(op_name, benefit)

    def match(self, op: Operation) -> bool:
        return str(op.name) == self._root_op_name


