"""Pattern rewrite system."""
from __future__ import annotations
from typing import List, Optional, Dict, Set, Callable, Type as PyType
from abc import ABC, abstractmethod
from .ir import (
    Operation, Region, Block, Value, OpResult, Type, Attribute,
    IntegerAttr, IntegerType
)


class PatternBenefit:
    """Represents the benefit of applying a pattern."""

    def __init__(self, benefit: int = 1) -> None:
        if benefit < 0:
            raise ValueError("Pattern benefit must be non-negative")
        self._benefit = benefit

    @property
    def value(self) -> int:
        return self._benefit

    def __lt__(self, other: PatternBenefit) -> bool:
        return self._benefit < other._benefit

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PatternBenefit):
            return False
        return self._benefit == other._benefit

    def __hash__(self) -> int:
        return hash(self._benefit)

    @staticmethod
    def impossible() -> PatternBenefit:
        return PatternBenefit(0)


class RewritePattern(ABC):
    """Base class for rewrite patterns."""

    def __init__(self, root_op_name: str, benefit: int = 1) -> None:
        self._root_op_name = root_op_name
        self._benefit = PatternBenefit(benefit)

    @property
    def root_operation_name(self) -> str:
        return self._root_op_name

    @property
    def benefit(self) -> PatternBenefit:
        return self._benefit

    @abstractmethod
    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        """Attempt to match and rewrite the operation. Return True on success."""

    def match(self, op: Operation) -> bool:
        """Check if the pattern matches without performing the rewrite."""
        return str(op.name) == self._root_op_name


class PatternRewriter:
    """Provides methods for pattern rewrite implementations."""

    def __init__(self) -> None:
        self._erased_ops: List[Operation] = []
        self._created_ops: List[Operation] = []
        self._replacements: Dict[int, Value] = {}
        self._insertion_point: Optional[Operation] = None

    def replace_op(self, op: Operation, new_values: List[Value]) -> None:
        """Replace all results of an operation with new values."""
        for i, result in enumerate(op.results):
            if i < len(new_values):
                result.replace_all_uses_with(new_values[i])
                self._replacements[id(result)] = new_values[i]
        self.erase_op(op)

    def replace_op_with_new_op(self, op: Operation, new_op: Operation) -> None:
        """Replace an operation with a new operation."""
        if op.parent_block:
            block = op.parent_block
            idx = block.operations.index(op)
            block.insert_operation(idx, new_op)
        self.replace_op(op, list(new_op.results))

    def erase_op(self, op: Operation) -> None:
        """Erase an operation from its parent block."""
        self._erased_ops.append(op)
        op.erase()

    def create_operation(self, name: str, operands: List[Value] = None,
                         result_types: List[Type] = None,
                         attributes: Dict[str, Attribute] = None) -> Operation:
        """Create a new operation."""
        new_op = Operation(name, operands=operands, result_types=result_types,
                           attributes=attributes)
        self._created_ops.append(new_op)
        return new_op

    def insert_before(self, op: Operation, new_op: Operation) -> None:
        """Insert a new operation before the given operation."""
        if op.parent_block:
            op.parent_block.insert_before(new_op, op)

    def insert_after(self, op: Operation, new_op: Operation) -> None:
        """Insert a new operation after the given operation."""
        if op.parent_block:
            op.parent_block.insert_after(new_op, op)

    def set_insertion_point_before(self, op: Operation) -> None:
        """Set the insertion point to just before an operation."""
        self._insertion_point = op

    @property
    def insertion_point(self) -> Optional[Operation]:
        return self._insertion_point

    @property
    def erased_ops(self) -> List[Operation]:
        return self._erased_ops

    @property
    def created_ops(self) -> List[Operation]:
        return self._created_ops


class PatternApplicator:
    """Applies patterns using a greedy driver."""

    def __init__(self, patterns: List[RewritePattern], max_iterations: int = 10) -> None:
        self._patterns = sorted(patterns, key=lambda p: p.benefit.value, reverse=True)
        self._max_iterations = max_iterations
        self._statistics: Dict[str, int] = {"num_rewrites": 0, "num_iterations": 0}

    @property
    def patterns(self) -> List[RewritePattern]:
        return self._patterns

    def apply_patterns_greedy(self, op: Operation) -> bool:
        """Apply patterns greedily until convergence or max iterations."""
        changed = False
        for _ in range(self._max_iterations):
            self._statistics["num_iterations"] += 1
            local_changed = False
            worklist: List[Operation] = []
            op.walk(worklist.append)
            for target_op in worklist:
                if target_op is not op and target_op.parent_block is None:
                    continue
                for pattern in self._patterns:
                    if not pattern.match(target_op):
                        continue
                    rewriter = PatternRewriter()
                    if pattern.match_and_rewrite(target_op, rewriter):
                        local_changed = True
                        self._statistics["num_rewrites"] += 1
                        break
            if not local_changed:
                break
            changed = True
        return changed

    @property
    def statistics(self) -> Dict[str, int]:
        return self._statistics


def apply_patterns_greedily(op: Operation, patterns: List[RewritePattern],
                            max_iterations: int = 10) -> bool:
    """Module-level helper mirroring MLIR's applyPatternsGreedily."""
    return PatternApplicator(patterns, max_iterations).apply_patterns_greedy(op)


class ConversionTarget:
    """Specifies legality of operations for dialect conversion."""

    class LegalityKind:
        LEGAL = "legal"
        ILLEGAL = "illegal"
        DYNAMIC = "dynamic"

    def __init__(self) -> None:
        self._op_legality: Dict[str, str] = {}
        self._dialect_legality: Dict[str, str] = {}
        self._dynamic_checks: Dict[str, Callable[[Operation], bool]] = {}

    def add_legal_op(self, op_name: str) -> None:
        self._op_legality[op_name] = self.LegalityKind.LEGAL

    def add_illegal_op(self, op_name: str) -> None:
        self._op_legality[op_name] = self.LegalityKind.ILLEGAL

    def add_dynamically_legal_op(self, op_name: str,
                                 callback: Callable[[Operation], bool]) -> None:
        self._op_legality[op_name] = self.LegalityKind.DYNAMIC
        self._dynamic_checks[op_name] = callback

    def add_legal_dialect(self, dialect_name: str) -> None:
        self._dialect_legality[dialect_name] = self.LegalityKind.LEGAL

    def add_illegal_dialect(self, dialect_name: str) -> None:
        self._dialect_legality[dialect_name] = self.LegalityKind.ILLEGAL

    def is_legal(self, op: Operation) -> bool:
        op_name = str(op.name)
        if op_name in self._op_legality:
            legality = self._op_legality[op_name]
            if legality == self.LegalityKind.LEGAL:
                return True
            elif legality == self.LegalityKind.ILLEGAL:
                return False
            elif legality == self.LegalityKind.DYNAMIC:
                check = self._dynamic_checks.get(op_name)
                return check(op) if check else False
        dialect = op.name.dialect_name
        if dialect in self._dialect_legality:
            return self._dialect_legality[dialect] == self.LegalityKind.LEGAL
        return True


class TypeConverter:
    """Converts types during dialect conversion."""

    def __init__(self) -> None:
        self._conversions: List[Callable[[Type], Optional[Type]]] = []

    def add_conversion(self, fn: Callable[[Type], Optional[Type]]) -> None:
        self._conversions.append(fn)

    def convert_type(self, type: Type) -> Optional[Type]:
        for conversion in self._conversions:
